-- ============================================================================
-- 0001_init.sql — RunA Log Technologies: initial Postgres schema
--
-- What this file is:
--   A hand-written Postgres DDL that mirrors prisma/schema.prisma 1:1
--   (model name = table name, field name = column name, no mapping).
--   It is the schema half of the SQLite -> Supabase migration kit described
--   in SUPABASE_MIGRATION.md. The data half is generated by
--   scripts/export-sqlite-data.ts into supabase/0002_data_export.sql,
--   which must be run AFTER this file.
--
-- Conventions (matching what Prisma itself would generate on Postgres):
--   * IDs are TEXT PRIMARY KEY — Prisma generates cuid() values in the app
--     layer, so no database default is needed.
--   * Prisma DateTime  -> TIMESTAMPTZ
--   * Prisma Float?    -> DOUBLE PRECISION
--   * @default(now())  -> DEFAULT now()
--   * updatedAt is maintained by Prisma in the application layer, so it has
--     no database default or trigger.
--   * Constraint/index names follow Prisma defaults
--     ("<Table>_<column>_fkey", "<Table>_<column>_key", "<Table>_<column>_idx")
--     so this schema stays recognizable if Prisma is later used against it.
--
-- How to apply:
--   Supabase Dashboard -> SQL Editor -> paste this file -> Run
--   (or: supabase db push with the Supabase CLI — see SUPABASE_MIGRATION.md)
--
-- Tables are created in dependency order: ProjectInquiry, Staff, Lead,
-- Activity, Client (every FK points to an earlier table).
-- ============================================================================

-- ----------------------------------------------------------------------------
-- ProjectInquiry — inquiries submitted through the contact / "Start a Project"
-- form. Managed in the admin panel (/admin).
-- ----------------------------------------------------------------------------
CREATE TABLE "ProjectInquiry" (
    "id"          TEXT        NOT NULL,
    "fullName"    TEXT        NOT NULL,
    "email"       TEXT        NOT NULL,
    "company"     TEXT,
    "service"     TEXT        NOT NULL,
    "budget"      TEXT,
    "timeline"    TEXT,
    "description" TEXT        NOT NULL,
    "status"      TEXT        NOT NULL DEFAULT 'new',
    "notes"       TEXT,
    "createdAt"   TIMESTAMPTZ NOT NULL DEFAULT now(),
    "updatedAt"   TIMESTAMPTZ NOT NULL,

    CONSTRAINT "ProjectInquiry_pkey" PRIMARY KEY ("id")
);

-- ----------------------------------------------------------------------------
-- Staff — team members who sign in to the staff panel (/staff).
-- passwordHash is a scrypt hash produced by the app (src/lib/password.ts);
-- hashes migrate as-is.
-- ----------------------------------------------------------------------------
CREATE TABLE "Staff" (
    "id"           TEXT        NOT NULL,
    "name"         TEXT        NOT NULL,
    "email"        TEXT        NOT NULL,
    "passwordHash" TEXT        NOT NULL,
    "role"         TEXT        NOT NULL DEFAULT 'staff',
    "active"       BOOLEAN     NOT NULL DEFAULT TRUE,
    "lastLoginAt"  TIMESTAMPTZ,
    "createdAt"    TIMESTAMPTZ NOT NULL DEFAULT now(),
    "updatedAt"    TIMESTAMPTZ NOT NULL,

    CONSTRAINT "Staff_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "Staff_email_key" UNIQUE ("email")
);

-- ----------------------------------------------------------------------------
-- Lead — sales leads (manual, CSV/XLSX import, or converted from an inquiry).
-- ----------------------------------------------------------------------------
CREATE TABLE "Lead" (
    "id"           TEXT             NOT NULL,
    "name"         TEXT             NOT NULL,
    "email"        TEXT,
    "phone"        TEXT,
    "company"      TEXT,
    "source"       TEXT             NOT NULL DEFAULT 'manual',
    "status"       TEXT             NOT NULL DEFAULT 'new',
    "value"        DOUBLE PRECISION,
    "notes"        TEXT,
    "inquiryId"    TEXT,
    "assignedToId" TEXT,
    "createdAt"    TIMESTAMPTZ      NOT NULL DEFAULT now(),
    "updatedAt"    TIMESTAMPTZ      NOT NULL,

    CONSTRAINT "Lead_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "Lead_inquiryId_key" UNIQUE ("inquiryId"),
    CONSTRAINT "Lead_inquiryId_fkey" FOREIGN KEY ("inquiryId")
        REFERENCES "ProjectInquiry" ("id")
        ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT "Lead_assignedToId_fkey" FOREIGN KEY ("assignedToId")
        REFERENCES "Staff" ("id")
        ON DELETE SET NULL ON UPDATE CASCADE
);

-- ----------------------------------------------------------------------------
-- Activity — scheduled calls / meetings / follow-ups with a lead.
-- ----------------------------------------------------------------------------
CREATE TABLE "Activity" (
    "id"          TEXT        NOT NULL,
    "leadId"      TEXT        NOT NULL,
    "type"        TEXT        NOT NULL DEFAULT 'call',
    "title"       TEXT        NOT NULL,
    "scheduledAt" TIMESTAMPTZ NOT NULL,
    "status"      TEXT        NOT NULL DEFAULT 'scheduled',
    "outcome"     TEXT,
    "notes"       TEXT,
    "createdById" TEXT,
    "createdAt"   TIMESTAMPTZ NOT NULL DEFAULT now(),
    "updatedAt"   TIMESTAMPTZ NOT NULL,

    CONSTRAINT "Activity_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "Activity_leadId_fkey" FOREIGN KEY ("leadId")
        REFERENCES "Lead" ("id")
        ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "Activity_createdById_fkey" FOREIGN KEY ("createdById")
        REFERENCES "Staff" ("id")
        ON DELETE SET NULL ON UPDATE CASCADE
);

-- ----------------------------------------------------------------------------
-- Client — paying / onboarded clients, usually converted from a won lead.
-- ----------------------------------------------------------------------------
CREATE TABLE "Client" (
    "id"        TEXT             NOT NULL,
    "leadId"    TEXT,
    "name"      TEXT             NOT NULL,
    "email"     TEXT,
    "phone"     TEXT,
    "company"   TEXT,
    "service"   TEXT,
    "status"    TEXT             NOT NULL DEFAULT 'onboarding',
    "value"     DOUBLE PRECISION,
    "startDate" TIMESTAMPTZ      NOT NULL DEFAULT now(),
    "notes"     TEXT,
    "createdAt" TIMESTAMPTZ      NOT NULL DEFAULT now(),
    "updatedAt" TIMESTAMPTZ      NOT NULL,

    CONSTRAINT "Client_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "Client_leadId_key" UNIQUE ("leadId"),
    CONSTRAINT "Client_leadId_fkey" FOREIGN KEY ("leadId")
        REFERENCES "Lead" ("id")
        ON DELETE SET NULL ON UPDATE CASCADE
);

-- ----------------------------------------------------------------------------
-- Indexes — the three that Prisma declares in schema.prisma, plus a few
-- obviously useful ones for the admin list/filter queries (status + dates).
-- ----------------------------------------------------------------------------
CREATE INDEX "Lead_assignedToId_idx"     ON "Lead" ("assignedToId");
CREATE INDEX "Lead_status_idx"           ON "Lead" ("status");
CREATE INDEX "Lead_createdAt_idx"        ON "Lead" ("createdAt");
CREATE INDEX "Activity_leadId_idx"       ON "Activity" ("leadId");
CREATE INDEX "Activity_createdById_idx"  ON "Activity" ("createdById");
CREATE INDEX "Activity_scheduledAt_idx"  ON "Activity" ("scheduledAt");
CREATE INDEX "ProjectInquiry_status_idx" ON "ProjectInquiry" ("status");
CREATE INDEX "ProjectInquiry_createdAt_idx" ON "ProjectInquiry" ("createdAt");
CREATE INDEX "Client_status_idx"         ON "Client" ("status");

-- The application accesses these tables server-side through Prisma. Do not
-- expose customer or staff data through the Supabase Data API by default.
ALTER TABLE "ProjectInquiry" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Staff"          ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Lead"           ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Activity"       ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Client"         ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE "ProjectInquiry", "Staff", "Lead", "Activity", "Client"
    FROM anon, authenticated;
